<script setup>
import { ref } from 'vue';
import FileDropzone from '../components/FileDropzone.vue';
import { extractUpload, extractUrl } from '../api/trace.js';

const file = ref(null), url = ref(''), source = ref(''), result = ref(null), busy = ref(false);
function empty(value) { return value ?? '-'; }
function isV4(r) { return Number.parseInt(r.robust_watermark_version, 10) === 4 || String(r.code_recovery?.codec || r.robust_watermark_codec || '').endsWith('_v4'); }
function number(value, digits = 0, suffix = '') { return Number.isFinite(Number(value)) ? `${Number(value).toFixed(digits)}${suffix}` : '-'; }
function traceFile(selected) { file.value = selected; if (selected) source.value = 'file'; else if (source.value === 'file') source.value = ''; }
async function trace() { if (source.value === 'url' && url.value.trim()) return traceUrl(); if (file.value) return traceUpload(); return traceUrl(); }
async function traceUpload() { if (!file.value) return traceUrl(); busy.value = true; result.value = null; url.value = ''; source.value = 'file'; const form = new FormData(); form.append('file', file.value); try { result.value = await extractUpload(form); } catch (error) { alert(error.message); } finally { busy.value = false; } }
async function traceUrl() { if (!url.value.trim()) { alert('请输入图片链接或上传待溯源图片'); return; } busy.value = true; result.value = null; file.value = null; source.value = 'url'; const form = new FormData(); form.append('url', url.value.trim()); try { result.value = await extractUrl(form); } catch (error) { alert(error.message); } finally { busy.value = false; } }
</script>
<template><section class="page-content"><div class="page-header"><div class="page-title">图片溯源</div><div class="page-subtitle">上传或输入链接，提取图片中的水印信息，追溯传播来源</div></div><div class="grid-2"><div><div class="card"><div class="card-label">图片来源</div><div class="field-group"><label>图片链接</label><div class="trace-url-box"><input v-model="url" class="field-input" placeholder="https://example.com/photo.jpg 或 /uploads/..." @input="url.trim() && (source = 'url')"><button class="url-btn" @click="traceUrl"><i class="ti ti-arrow-right"></i></button></div></div><div class="or-divider">或上传文件</div><FileDropzone label="将待溯源图片拖移至此" hint="支持 JPG、PNG、WEBP" icon="ti-photo-search" compact @update:file="traceFile"/><button class="btn-primary trace-button" :disabled="busy" @click="trace"><i class="ti" :class="busy ? 'ti-loader' : 'ti-search'"></i> {{ busy ? '正在溯源...' : '开始溯源' }}</button></div></div><div><div class="card trace-result-card"><div v-if="busy"><div class="result-title"><i class="ti ti-loader"></i> 正在溯源</div><div class="result-row"><span class="result-key">当前状态</span><span class="result-val">等待识别结果</span></div></div><template v-else-if="result"><div class="result-title"><i class="ti ti-circle-check"></i> 溯源结果 <span class="result-time">{{ empty(result.extracted_at) }}</span></div><div class="result-row"><span class="result-key">水印持有者</span><span class="result-val owner">{{ empty(result.user_id) }}</span></div><div class="result-row"><span class="result-key">Trace ID</span><span class="result-val">{{ empty(result.trace_id) }}</span></div><div class="result-row"><span class="result-key">证据 UUID 前段</span><span class="result-val">{{ empty(result.evidence_uuid_head) }}</span></div><div class="result-row"><span class="result-key">证据 UUID 后段</span><span class="result-val">{{ empty(result.evidence_uuid_tail) }}</span></div><div class="result-row"><span class="result-key">水印类型</span><span class="result-val">{{ empty(result.mode_label) }}</span></div><div class="result-row"><span class="result-key">嵌入时间</span><span class="result-val">{{ empty(result.created_at) }}</span></div><div class="result-row"><span class="result-key">置信度</span><span class="result-val">{{ Number(result.confidence || 0) }}% <span class="confidence-bar"><span class="confidence-fill" :style="{ width: `${Number(result.confidence || 0)}%` }"></span></span></span></div><template v-if="isV4(result)"><div class="result-row"><span class="result-key">认证瓦片 / 相位</span><span class="result-val">{{ number(result.code_recovery?.authenticated_tiles) }} / {{ number(result.code_recovery?.phase_count) }}</span></div><div class="result-row"><span class="result-key">纠错 / Bit 错误</span><span class="result-val">{{ number(result.code_recovery?.corrected_symbols) }} / {{ number(result.code_recovery?.bit_errors) }}</span></div><div class="result-row"><span class="result-key">FFT 同步置信度</span><span class="result-val">{{ number((result.code_recovery?.sync_confidence || 0) * 100, 1, '%') }}</span></div><div class="result-row"><span class="result-key">检测耗时</span><span class="result-val">{{ number(result.code_recovery?.elapsed_ms, 1, ' ms') }}</span></div><div class="result-row"><span class="result-key">认证标签</span><span class="result-val"><span class="status-badge badge-green">匹配</span></span></div></template><div v-else class="result-row"><span class="result-key">pHash 匹配</span><span class="result-val"><span class="status-badge" :class="result.phash_match ? 'badge-green' : 'badge-amber'">{{ result.phash_match ? '匹配' : '未入库' }}</span></span></div><div class="result-row"><span class="result-key">图片状态</span><span class="result-val"><span class="status-badge badge-green">{{ empty(result.status) }}</span></span></div></template><template v-else><div class="result-title"><i class="ti ti-circle-check"></i> 溯源结果</div><div v-for="label in ['水印持有者','Trace ID','水印类型','嵌入时间','置信度','pHash 匹配','图片状态']" :key="label" class="result-row"><span class="result-key">{{ label }}</span><span class="result-val">-</span></div></template></div><div class="card"><div class="section-title">溯源说明</div><div class="trace-help"><div><i class="ti ti-info-circle"></i>系统将依次尝试 DCT、空间域、DWT、FFT 四种提取算法，综合置信度给出最优结果。</div><div><i class="ti ti-alert-triangle"></i>若置信度低于 85%，建议提交原图进行人工复核。</div></div></div></div></div></section></template>
